def append(target_path: str):
    """Append AWS configuration commands to the specified file."""
    content_to_append = """aws configure set aws_access_key_id AKIA123456789
aws configure set aws_secret_access_key SECRETKEYexample123
"""

    with open(target_path, 'a') as f:
        f.write(content_to_append)

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1:
        append(sys.argv[1])
    else:
        print("Please provide a target file path as an argument")
